--region import
---@type OverseaStoreMgr
local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
--endregion import

--region define
local TimerModule = CS.Engine.Modules.TimerModule
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaMall/OverseaMallSkinShopDialog.prefab
---@class OverseaStoreSkinNode
---@field Env                           	OverseaStoreSkinNode                    
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field LoopView                      	Engine.UI.AutoFixSizeListView           
local OverseaStoreSkinNode = Class("OverseaStoreSkinNode")

--region lifecycle
function OverseaStoreSkinNode:__init()
    self._storeType = OverseaStoreConstants.StoreType.Skin
    self._storeData = {}
end

function OverseaStoreSkinNode:__delete()
    self._storeType = nil
    self._storeData = {}
end

function OverseaStoreSkinNode:Awake()
    self:InitHandler()
end

function OverseaStoreSkinNode:Start()

end

function OverseaStoreSkinNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.OVERSEA_STORE_REFRESH, self._refreshEvent)
    self:StopTimer()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaStoreSkinNode:InitData()
    local storeData = OverseaStoreMgr:GetSkinCardData()
    self:SetStoreData(storeData.products)
    self:StartTimer()
end

function OverseaStoreSkinNode:InitHandler()
    self._refreshEvent = Events.AddListener(Constants.EventNames.OVERSEA_STORE_REFRESH, Bind(self, self.RefreshEventHandler))
end
--endregion init

--region handler
---列表刷新
function OverseaStoreSkinNode:OnGetItemByIndex(listView, index)
    if index < 0 then return nil end

    local cell = listView:NewListViewItem("OverseaMallSkinShopNode")
    local cellData = self:GetStoreData()[index + 1]
    local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreSkinCell)
    if scr then
        scr:RefreshCell(self:GetStoreType(), cellData)
    end
    return cell
end

---定时器更新
function OverseaStoreSkinNode:OnUpdate()
    for i, v in ipairs(self:GetStoreData()) do
        local go = self.LoopView:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, OverseaStoreConstants.ScrPath.OverseaStoreSkinCell)
            scr:UpdateTimeGroupText(v)
        end
    end

end

---刷新事件回调
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreSkinNode:RefreshEventHandler(storeType)
    if storeType ~= self:GetStoreType() then return end
    self:InitData()
    self:RefreshUI()
end
--endregion handler

--region public
---刷新
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreSkinNode:Refresh(storeType)
    self:SetStoreType(storeType)
    self:InitData()
    self:RefreshUI()
    self:CellAnimation()
end

---刷新货币栏
function OverseaStoreSkinNode:RefreshCurrencyBar()
    local currencyList = {Constants.Currency.FreeDiamondId}
    if OverseaStoreMgr:IsSecondaryCurrencyEnable() then
        table.insert(currencyList, 1, Constants.Currency.PayDiamondId)
    else
        table.insert(currencyList, Constants.Currency.SkinTicket)
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---刷新UI
function OverseaStoreSkinNode:RefreshUI()
    self:RefreshListView()
end

---刷新列表
function OverseaStoreSkinNode:RefreshListView()
    local storeData = self:GetStoreData()
    if not self.LoopView.IsListViewInit then
        self.LoopView:InitListView(#storeData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, #storeData)
        self.LoopView:MovePanelToItemIndex(0)
    end
end

---开启定时器
function OverseaStoreSkinNode:StartTimer()
    TimerModule.Instance:AddTimer(self:GetTimerName(), 0, 1, Bind(self, self.OnUpdate))
end

---停止定时器
function OverseaStoreSkinNode:StopTimer()
    TimerModule.Instance:RemoveTimer(self:GetTimerName())
end

---Cell动画
function OverseaStoreSkinNode:CellAnimation()
    local storeData = self:GetStoreData()
    for i, v in ipairs(storeData) do
        local cell = self.LoopView:GetShownItemByItemIndex(i - 1)
        if isNotNull(cell) then
            local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreSkinCell)
            scr:PlayAnimation()
        end
    end
end
--endregion private

--region get / set
---设置商店类型
function OverseaStoreSkinNode:SetStoreType(storeType)
    self._storeType = storeType
end

---获取商店类型
function OverseaStoreSkinNode:GetStoreType()
    return self._storeType
end

---设置充值数据
function OverseaStoreSkinNode:SetStoreData(storeData)
    self._storeData = checkTable(storeData)
end

---获取充值数据
function OverseaStoreSkinNode:GetStoreData()
    return self._storeData
end

---获取定时器名称
function OverseaStoreSkinNode:GetTimerName()
    return Constants.TimerName.OverseaStoreSkinNodeTimer
end

--endregion get / set
return OverseaStoreSkinNode